146	// 原子改名，保证崩溃后只会看到旧文件或新文件。
147	func writeAtomic(dir, name string, data []byte) error {
148		tmp := filepath.Join(dir, ".tmp-"+name+"-"+randomSuffix())
149		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
