1	package world
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8	)
9	
10	// RecordInfo 描述一次保存产生的记录的元信息。
11	type RecordInfo struct {
12		// ID 是记录在存档目录内的唯一标识。
13		ID RecordID
14		// Parent 是父记录标识；直接建立的槽首条记录为空。
15		Parent RecordID
16		// SlotFirst 表示这是所在槽的首条记录（根记录或分支记录）。
17		SlotFirst bool
18		// Version 是记录中世界规则的版本。
19		Version string
20	}
21	
22	// slotPointer 是槽指针文件的磁盘内容，指向该槽当前最新记录。
23	//
24	// History 按该槽“保存生效的次序”记录全部属于本槽的记录标识，最新在前，
25	// 末尾是槽首条记录（直接建立的根记录或分支首记录）。它只在对应记录文件
26	// 已完整落盘后才随指针原子更新，因此绝不会包含写了一半的残留文件、写完
27	// 但尚未完成保存的孤儿记录，或 CAS 竞争失败的写入。恢复读取据此遍历，
28	// 不依赖文件修改时间，也不信任受损记录文件里读出的父标识或槽首标记。
29	//
30	// 旧版本写出的指针没有 History 字段；读取时会在内存中按校验通过的父链
31	// 回退重建，不要求用户转换数据。
32	type slotPointer struct {
33		Latest  RecordID   `json:"latest"`
34		History []RecordID `json:"history,omitempty"`
35	}
36	
37	// archiveMarker 是存档目录的标记文件。
38	type archiveMarker struct {
39		Format int `json:"format"`
40	}
41	
42	// Archive 是一个本地存档目录句柄。多个进程或多个实例可以同时打开
43	// 同一目录；所有写入通过目录内的 flock 串行化。
44	type Archive struct {
45		dir string
46	}
47	
48	const (
49		markerName  = "archive.json"
50		recordsName = "records"
51		slotsName   = "slots"
52	)
53	
54	// Create 在指定目录建立新的存档。目录会被创建；若该目录已经是一个
55	// 存档则返回错误，以免覆盖已有数据。
56	func Create(dir string) (*Archive, error) {
57		if err := os.MkdirAll(dir, 0o755); err != nil {
58			return nil, err
59		}
60		markerPath := filepath.Join(dir, markerName)
61		f, err := os.OpenFile(markerPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
62		if err != nil {
63			if errors.Is(err, os.ErrExist) {
64				return nil, &ConflictError{Reason: "目录已是一个存档: " + dir}
65			}
66			return nil, err
67		}
68		markerData, _ := json.Marshal(archiveMarker{Format: archiveFormatVersion})
69		if _, err := f.Write(markerData); err != nil {
70			f.Close()
71			return nil, err
72		}
73		if err := f.Close(); err != nil {
74			return nil, err
75		}
76		for _, sub := range []string{recordsName, slotsName} {
77			if err := os.MkdirAll(filepath.Join(dir, sub), 0o755); err != nil {
78				return nil, err
79			}
80		}
81		// 预先建立锁文件并同步目录，使之后的打开更稳妥。
82		if lf, err := os.OpenFile(filepath.Join(dir, "lock"),
83			os.O_RDWR|os.O_CREATE, 0o600); err == nil {
84			lf.Close()
85		}
86		if err := syncDir(dir); err != nil {
87			return nil, err
88		}
89		return &Archive{dir: dir}, nil
90	}
91	
92	// Open 打开一个此前由 Create 建立的存档目录。
93	func Open(dir string) (*Archive, error) {
94		path := filepath.Join(dir, markerName)
95		f, err := os.Open(path)
96		if err != nil {
97			if errors.Is(err, os.ErrNotExist) {
98				return nil, &NotFoundError{}
99			}
100			return nil, err
101		}
102		defer f.Close()
103		var m archiveMarker
104		if err := json.NewDecoder(f).Decode(&m); err != nil {
105			return nil, &CorruptError{Reason: "存档标记无法解析"}
106		}
107		if m.Format != archiveFormatVersion {
108			return nil, &CorruptError{Reason: "不支持的存档格式版本"}
109		}
110		for _, sub := range []string{recordsName, slotsName} {
111			if fi, err := os.Stat(filepath.Join(dir, sub)); err != nil || !fi.IsDir() {
112				return nil, &CorruptError{Reason: "存档目录结构不完整: 缺少 " + sub}
113			}
114		}
115		return &Archive{dir: dir}, nil
116	}
117	
118	// Dir 返回存档目录路径。
119	func (a *Archive) Dir() string { return a.dir }
120	
121	func (a *Archive) slotPath(slot string) string {
122		return filepath.Join(a.dir, slotsName, slot+".json")
123	}
124	
125	// validSlotName 拒绝空名以及可能逃逸 slots 目录的名字。
126	func validSlotName(slot string) bool {
127		if slot == "" || slot == "." || slot == ".." {
128			return false
129		}
130		if filepath.IsAbs(slot) {
131			return false
132		}
133		for _, r := range slot {
134			if r == '/' || r == '\\' || r == 0 {
135				return false
136			}
137		}
138		return filepath.Clean(slot) == slot
139	}
140	
141	// readSlotPointerLocked 在调用方已持锁的前提下读取并解析槽指针文件。
142	func (a *Archive) readSlotPointerLocked(slot string) (slotPointer, error) {
143		data, err := os.ReadFile(a.slotPath(slot))
144		if err != nil {
145			if errors.Is(err, os.ErrNotExist) {
146				return slotPointer{}, &NotFoundError{Slot: slot}
147			}
148			return slotPointer{}, err
149		}
150		var p slotPointer
151		if err := json.Unmarshal(data, &p); err != nil {
152			return slotPointer{}, &CorruptError{Slot: slot, Reason: "槽指针无法解析"}
153		}
154		if p.Latest == "" {
155			return slotPointer{}, &CorruptError{Slot: slot, Reason: "槽指针为空"}
156		}
157		return p, nil
158	}
159	
160	// readLatestLocked 在调用方已持锁的前提下读取槽当前最新记录标识。
161	func (a *Archive) readLatestLocked(slot string) (RecordID, error) {
162		p, err := a.readSlotPointerLocked(slot)
163		if err != nil {
164			return "", err
165		}
166		return p.Latest, nil
167	}
168	
169	// Save 在存档中保存一个世界。
170	//
171	// 首次保存会创建同名存档槽；槽名已存在时返回 *ConflictError。
172	// 成功后返回新记录的标识，记录包含完整世界数据，且没有父记录。
173	func (a *Archive) Save(slot string, w *World) (RecordInfo, error) {
174		if !validSlotName(slot) {
175			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "非法存档槽名"}
176		}
177		st := w.Snapshot()
178	
179		lock, err := acquireLock(a.dir)
180		if err != nil {
181			return RecordInfo{}, err
182		}
183		defer lock.release()
184	
185		// 持锁后再次确认槽不存在。
186		if _, err := a.readLatestLocked(slot); err == nil {
187			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "存档槽名已存在"}
188		} else if !errors.As(err, new(*NotFoundError)) {
189			return RecordInfo{}, err
190		}
191	
192		id, err := newRecordID()
193		if err != nil {
194			return RecordInfo{}, err
195		}
196		env := &envelope{
197			Format:    archiveFormatVersion,
198			ID:        id,
199			SlotFirst: true,
200			State:     st,
201		}
202		env.Checksum = computeChecksum(env)
203		if err := writeRecord(a.dir, env); err != nil {
204			return RecordInfo{}, err
205		}
206		if err := a.createSlotPointer(slot, id); err != nil {
207			return RecordInfo{}, err
208		}
209		return RecordInfo{ID: id, SlotFirst: true, Version: st.Rules.Version}, nil
210	}
211	
212	// createSlotPointer 以“临时文件写全 + os.Link 原子建立”的方式创建槽
213	// 指针：Link 在目标已存在时失败，因此重名会被明确拒绝，同时崩溃后
214	// 要么没有该槽，要么指向一份完整记录，绝不会留下半写的指针。新槽的
215	// 历史索引只含其首条记录本身——分支槽不会把来源槽的记录计入候选。
216	func (a *Archive) createSlotPointer(slot string, id RecordID) error {
217		slotsDir := filepath.Join(a.dir, slotsName)
218		final := a.slotPath(slot)
219		data, _ := json.MarshalIndent(slotPointer{
220			Latest:  id,
221			History: []RecordID{id},
222		}, "", "  ")
223	
224		tmp := filepath.Join(slotsDir, ".new-"+slot+"-"+randomSuffix()+".tmp")
225		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
226		if err != nil {
227			return err
228		}
229		if _, err := f.Write(data); err != nil {
230			f.Close()
231			os.Remove(tmp)
232			return err
233		}
234		if err := f.Sync(); err != nil {
235			f.Close()
236			os.Remove(tmp)
237			return err
238		}
239		if err := f.Close(); err != nil {
240			os.Remove(tmp)
241			return err
242		}
243		if err := os.Link(tmp, final); err != nil {
244			os.Remove(tmp)
245			if errors.Is(err, os.ErrExist) {
246				return &ConflictError{Slot: slot, Reason: "存档槽名已存在"}
247			}
248			return err
249		}
250		os.Remove(tmp)
251		return syncDir(slotsDir)
252	}
253	
254	// Replace 用世界当前状态覆盖槽的最新记录。
255	//
256	// expected 必须是调用方此前读到的记录标识，并且它仍是该槽最新记录，
257	// 写入才会发生；否则返回 *ConflictError。新记录的父记录就是被覆盖的
258	// 那次记录。同一目录下并发覆盖同一父记录时只有一个成功。
259	func (a *Archive) Replace(slot string, w *World, expected RecordID) (RecordInfo, error) {
260		if !validSlotName(slot) {
261			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "非法存档槽名"}
262		}
263		if expected == "" {
264			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "覆盖必须提供所依据的记录标识"}
265		}
266		st := w.Snapshot()
267	
268		lock, err := acquireLock(a.dir)
269		if err != nil {
270			return RecordInfo{}, err
271		}
272		defer lock.release()
273	
274		pointer, err := a.readSlotPointerLocked(slot)
275		if err != nil {
276			return RecordInfo{}, err
277		}
278		if pointer.Latest != expected {
279			return RecordInfo{}, &ConflictError{
280				Slot:   slot,
281				Reason: "所依据的记录已不是该槽最新记录",
282			}
283		}
284	
285		id, err := newRecordID()
286		if err != nil {
287			return RecordInfo{}, err
288		}
289		env := &envelope{
290			Format: archiveFormatVersion,
291			ID:     id,
292			Parent: expected,
293			State:  st,
294		}
295		env.Checksum = computeChecksum(env)
296		if err := writeRecord(a.dir, env); err != nil {
297			return RecordInfo{}, err
298		}
299		if err := a.commitSlotPointerLocked(slot, pointer, expected, id); err != nil {
300			return RecordInfo{}, err
301		}
302		return RecordInfo{
303			ID:      id,
304			Parent:  expected,
305			Version: st.Rules.Version,
306		}, nil
307	}
308	
309	// commitSlotPointerLocked 在记录文件已完整落盘后，原子更新槽指针：指向
310	// 新记录，并把历史索引按保存次序前置新记录。历史索引只在此刻（记录已
311	// 完整生效）才更新，因此残留临时文件与写完但未完成保存的孤儿记录绝不会
312	// 进入恢复候选。
313	func (a *Archive) commitSlotPointerLocked(slot string, oldPointer slotPointer, oldLatest, newID RecordID) error {
314		history, err := a.nextSlotHistoryLocked(oldPointer, oldLatest, newID)
315		if err != nil {
316			return err
317		}
318		return a.persistSlotPointerLocked(slot, slotPointer{Latest: newID, History: history})
319	}
320	
321	// replaceSlotPointer 直接把槽指针指向 id，不附带历史索引。它仅用于测试
322	// 中模拟旧版本或外部写入器留下的指针；生产写入路径一律走
323	// commitSlotPointerLocked 以维护历史索引。
324	func (a *Archive) replaceSlotPointer(slot string, id RecordID) error {
325		return a.persistSlotPointerLocked(slot, slotPointer{Latest: id})
326	}
327	
328	// Branch 从 srcSlot 的指定历史记录 src 分出新槽 dstSlot。
329	//
330	// 新槽的首条记录以 src 为父记录，完整复制当时的种子、规则和状态。
331	// 目标槽名已存在时返回 *ConflictError。源记录必须校验通过。
332	func (a *Archive) Branch(srcSlot string, src RecordID, dstSlot string) (RecordInfo, error) {
333		if !validSlotName(srcSlot) {
334			return RecordInfo{}, &ConflictError{Slot: srcSlot, Reason: "非法源存档槽名"}
335		}
336		if !validSlotName(dstSlot) {
337			return RecordInfo{}, &ConflictError{Slot: dstSlot, Reason: "非法目标存档槽名"}
338		}
339		if src == "" {
340			return RecordInfo{}, &NotFoundError{Slot: srcSlot}
341		}
342	
343		lock, err := acquireLock(a.dir)
344		if err != nil {
345			return RecordInfo{}, err
346		}
347		defer lock.release()
348	
349		srcEnv, err := a.loadAndVerifyLocked(src)
350		if err != nil {
351			return RecordInfo{}, err
352		}
353		// 确认源记录确实属于源槽的历史链，避免拿别的槽的记录冒充分支源。
354		if err := a.assertInSlotHistoryLocked(srcSlot, src); err != nil {
355			return RecordInfo{}, err
356		}
357		// 目标槽重名拒绝创建。
358		if _, err := a.readLatestLocked(dstSlot); err == nil {
359			return RecordInfo{}, &ConflictError{Slot: dstSlot, Reason: "目标存档槽名已存在"}
360		} else if !errors.As(err, new(*NotFoundError)) {
361			return RecordInfo{}, err
362		}
363	
364		id, err := newRecordID()
365		if err != nil {
366			return RecordInfo{}, err
367		}
368		env := &envelope{
369			Format:    archiveFormatVersion,
370			ID:        id,
371			Parent:    src,
372			SlotFirst: true,
373			// 完整复制当时的世界数据；此后两槽各自保存互不影响。
374			State: cloneState(srcEnv.State),
375		}
376		env.Checksum = computeChecksum(env)
377		if err := writeRecord(a.dir, env); err != nil {
378			return RecordInfo{}, err
379		}
380		if err := a.createSlotPointer(dstSlot, id); err != nil {
381			return RecordInfo{}, err
382		}
383		return RecordInfo{
384			ID:        id,
385			Parent:    src,
386			SlotFirst: true,
387			Version:   env.State.Rules.Version,
388		}, nil
389	}
390	
391	// assertInSlotHistoryLocked 确认 id 位于 slot 自身的历史次序中（分支槽
392	// 的历史只含它自己保存成功的记录，不含来源槽记录）。
393	func (a *Archive) assertInSlotHistoryLocked(slot string, id RecordID) error {
394		history, err := a.slotHistoryLocked(slot)
395		if err != nil {
396			return err
397		}
398		for _, cid := range history {
399			if cid == id {
400				return nil
401			}
402		}
403		return &NotFoundError{Slot: slot, Record: id}
404	}
405	
406	// slotHistoryLocked 返回该槽按保存生效次序排列的记录标识（最新在前、
407	// 槽首记录在末尾）。
408	//
409	// 优先使用指针内嵌的历史索引；旧版本指针没有该索引时，在内存中沿
410	// “校验通过”的记录父链回退重建，绝不在读取路径上改写目录。重建在缺失、
411	// 无法解析或校验不过的记录处停止——无法确认归属的更老记录不再使用。
412	// 槽首标记只取自校验通过的信封，因此受损记录里被篡改的父标识或槽首
413	// 标记既不能把遍历引向别的槽，也不能遮住本槽更早的可用记录。
414	func (a *Archive) slotHistoryLocked(slot string) ([]RecordID, error) {
415		p, err := a.readSlotPointerLocked(slot)
416		if err != nil {
417			return nil, err
418		}
419		if len(p.History) > 0 {
420			// 以 Latest 为链头做一次去重规范化，容忍索引中的重复项。
421			return dedupeRecordIDs(append([]RecordID{p.Latest}, p.History...)), nil
422		}
423		return a.rebuildHistoryLocked(p.Latest)
424	}
425	
426	// rebuildHistoryLocked 从 latest 起沿校验通过的父链在内存中重建历史，
427	// 只返回仍能确认属于本槽的记录；在缺失、无法解析或校验不过的记录处停止。
428	func (a *Archive) rebuildHistoryLocked(latest RecordID) ([]RecordID, error) {
429		var chain []RecordID
430		seen := map[RecordID]bool{}
431		cur := latest
432		for cur != "" {
433			if seen[cur] {
434				return nil, &CorruptError{Record: cur, Reason: "历史链出现环"}
435			}
436			seen[cur] = true
437			env, err := a.loadAndVerifyLocked(cur)
438			if err != nil {
439				// 缺失、无法解析或校验不过：无法继续确认更老记录的归属，
440				// 旧历史在此断裂；已确认的部分仍可使用。
441				return chain, nil
442			}
443			chain = append(chain, cur)
444			if env.SlotFirst {
445				return chain, nil
446			}
447			cur = env.Parent
448		}
449		return chain, nil
450	}
451	
452	// dedupeRecordIDs 按首次出现次序去重记录标识。
453	func dedupeRecordIDs(ids []RecordID) []RecordID {
454		seen := map[RecordID]bool{}
455		out := ids[:0]
456		for _, id := range ids {
457			if id == "" || seen[id] {
458				continue
459			}
460			seen[id] = true
461			out = append(out, id)
462		}
463		return out
464	}
465	
466	// persistSlotPointerLocked 以原子改名写出槽指针。
467	func (a *Archive) persistSlotPointerLocked(slot string, p slotPointer) error {
468		data, _ := json.MarshalIndent(p, "", "  ")
469		return writeAtomic(filepath.Join(a.dir, slotsName), slot+".json", data)
470	}
471	
472	// nextSlotHistory 在一次以 oldLatest 为被覆盖/升级记录的成功写入后，
473	// 生成新指针应持有的历史次序：新记录在最前，其余沿用此前已确认属于
474	// 本槽的记录。旧指针无索引时在内存中回退重建（不完整也照样承接），
475	// 从而让旧历史在第一次成功覆盖或升级后获得完整恢复能力。
476	func (a *Archive) nextSlotHistoryLocked(oldPointer slotPointer, oldLatest, newID RecordID) ([]RecordID, error) {
477		base := oldPointer.History
478		if len(base) == 0 {
479			rebuilt, err := a.rebuildHistoryLocked(oldLatest)
480			if err != nil {
481				return nil, err
482			}
483			base = rebuilt
484		}
485		return dedupeRecordIDs(append([]RecordID{newID}, base...)), nil
486	}
487	
488	// Slots 返回所有存档槽名。
489	func (a *Archive) Slots() ([]string, error) {
490		entries, err := os.ReadDir(filepath.Join(a.dir, slotsName))
491		if err != nil {
492			return nil, err
493		}
494		var names []string
495		for _, e := range entries {
496			if e.IsDir() {
497				continue
498			}
499			name := e.Name()
500			if len(name) > 5 && name[len(name)-5:] == ".json" {
501				names = append(names, name[:len(name)-5])
502			}
503		}
504		return names, nil
505	}
