7	
8	// BlockerKind 表示升级阻碍的类型。
9	type BlockerKind string
10	
11	const (
12		// BlockerLocation 表示角色所在地点在目标规则中已不存在。
13		BlockerLocation BlockerKind = "location"
14		// BlockerItem 表示角色携带的某种物品在目标规则中已不被允许。
15		BlockerItem BlockerKind = "item"
16		// BlockerLimit 表示角色携带总量超过目标规则给出的上限。
17		BlockerLimit BlockerKind = "limit"
18	)
19	
20	// Blocker 描述一条“目标规则无法原样承接当前角色状态”的具体阻碍。
21	type Blocker struct {
22		// Character 是受阻碍的角色标识。
23		Character string
24		// Kind 是阻碍类型。
25		Kind BlockerKind
26		// Location 是缺失的地点（Kind 为 BlockerLocation 时有值）。
27		Location string
28		// Item 是被移除的物品种类（Kind 为 BlockerItem 时有值）。
29		Item string
30		// Total 是角色当前携带总量（Kind 为 BlockerLimit 时有值）。
31		Total int
32		// Limit 是目标规则给出的新上限（Kind 为 BlockerLimit 时有值）。
33		Limit int
34	}
35	
36	// UpgradeCheck 描述对槽当前最新记录与目标规则的兼容性检查结果。
37	type UpgradeCheck struct {
38		// RecordID 是所检查的来源记录标识（槽当前最新记录）。
39		RecordID RecordID
40		// OldVersion 是来源记录的规则版本。
41		OldVersion string
42		// TargetVersion 是目标规则版本。
43		TargetVersion string
44		// Compatible 表示目标规则能否原样承接当前角色状态。
45		Compatible bool
46		// Blockers 是全部阻碍，按角色标识、物品标识排序；重复检查输出顺序一致。
47		Blockers []Blocker
48	}
49	
50	// UpgradeResult 是升级的返回结果。
51	type UpgradeResult struct {
52		// Check 是对当前来源记录与目标规则的兼容性检查结果。
53		Check UpgradeCheck
54		// Record 是成功时新记录的元信息；被阻碍时为零值。
55		Record RecordInfo
56	}
57	
58	// checkCompatibility 计算用 target 规则原样承接 st 中全部角色状态的阻碍。
59	//
60	// 兼容只判断能否原样承接当前角色状态：每个角色所在地点仍存在，已列出的
61	// 物品种类仍被允许（数量为零也算），各角色携带总量不超过目标上限；目标中
62	// 没有该角色上限时表示不设上限。允许删去无人所在的地点、不再出现的物品种
63	// 类或旧连通关系，也允许增加内容。升级后移动和物品变化按目标规则处理。
64	func checkCompatibility(st State, target Rules) []Blocker {
65		locSet := make(map[string]struct{}, len(target.Locations))
66		for _, l := range target.Locations {
67			locSet[l] = struct{}{}
68		}
69		kindSet := make(map[string]struct{}, len(target.ItemKinds))
70		for _, k := range target.ItemKinds {
71			kindSet[k] = struct{}{}
72		}
73		var blockers []Blocker
74		for _, ch := range st.Characters {
75			if _, ok := locSet[ch.Location]; !ok {
76				blockers = append(blockers, Blocker{
77					Character: ch.ID,
78					Kind:      BlockerLocation,
79					Location:  ch.Location,
80				})
81			}
82			total := 0
83			for _, it := range ch.Items {
84				if _, ok := kindSet[it.Item]; !ok {
85					blockers = append(blockers, Blocker{
86						Character: ch.ID,
87						Kind:      BlockerItem,
88						Item:      it.Item,
89					})
90				}
91				total += it.Count
92			}
93			if limit, ok := target.CarryLimits[ch.ID]; ok && total > limit {
94				blockers = append(blockers, Blocker{
95					Character: ch.ID,
96					Kind:      BlockerLimit,
97					Total:     total,
98					Limit:     limit,
99				})
100			}
101		}
102		// 同类问题按角色标识、物品标识排序；location/limit 阻碍没有物品标识，
103		// 以空物品标识参与排序，保证重复检查输出顺序一致。跨类别按
104		// location、item、limit 的自然顺序分组，便于阅读。
105		kindRank := func(k BlockerKind) int {
106			switch k {
107			case BlockerLocation:
108				return 0
109			case BlockerItem:
110				return 1
111			case BlockerLimit:
112				return 2
113			}
114			return 3
115		}
116		sort.SliceStable(blockers, func(i, j int) bool {
117			if blockers[i].Character != blockers[j].Character {
118				return blockers[i].Character < blockers[j].Character
119			}
120			if blockers[i].Kind != blockers[j].Kind {
121				return kindRank(blockers[i].Kind) < kindRank(blockers[j].Kind)
122			}
123			return blockers[i].Item < blockers[j].Item
124		})
125		return blockers
126	}
127	
128	// checkUpgradeLocked 在调用方已持锁（共享或排他均可）的前提下读取并校验
129	// 槽当前最新记录，计算目标规则的兼容性。返回检查结果与来源记录信封。
130	func (a *Archive) checkUpgradeLocked(slot string, acceptedVersions []string, target Rules) (UpgradeCheck, *envelope, error) {
131		latest, err := a.readLatestLocked(slot)
132		if err != nil {
133			return UpgradeCheck{}, nil, err
134		}
135		env, err := a.loadAndVerifyLocked(latest)
136		if err != nil {
137			if ce, ok := err.(*CorruptError); ok {
138				ce.Slot = slot
139			}
140			return UpgradeCheck{}, nil, err
141		}
142		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
143			return UpgradeCheck{}, nil, &VersionRejectedError{
144				Slot:     slot,
145				Record:   latest,
146				Version:  env.State.Rules.Version,
147				Accepted: append([]string(nil), acceptedVersions...),
148			}
149		}
150		if target.Version == env.State.Rules.Version {
151			return UpgradeCheck{}, nil, &RuleError{Reason: "目标规则版本必须与来源记录版本不同"}
152		}
153		check := UpgradeCheck{
154			RecordID:      latest,
155			OldVersion:    env.State.Rules.Version,
156			TargetVersion: target.Version,
157		}
158		blockers := checkCompatibility(env.State, target)
159		check.Compatible = len(blockers) == 0
160		check.Blockers = blockers
161		return check, env, nil
162	}
163	
164	// CheckUpgrade 检查槽当前最新记录能否在目标规则下继续使用。
165	//
166	// 检查只读取来源记录并计算兼容性，不改变世界、历史或槽当前记录，也不会
167	// 替换记录中的规则。target 必须先满足规则自身的合法性要求，且版本与来源
168	// 记录不同（版本只按相等判断，不按数字大小限制升级）。
169	//
170	// 目标规则非法返回 *RuleError；版本相同返回 *RuleError；来源损坏返回
171	// *CorruptError；来源版本不在 acceptedVersions 内返回 *VersionRejectedError；
172	// 槽不存在沿用现有不存在错误。
173	func (a *Archive) CheckUpgrade(slot string, acceptedVersions []string, target Rules) (UpgradeCheck, error) {
174		if !validSlotName(slot) {
175			return UpgradeCheck{}, &NotFoundError{Slot: slot}
176		}
177		if err := validateRules(target); err != nil {
178			return UpgradeCheck{}, err
179		}
180		lock, err := acquireSharedLock(a.dir)
181		if err != nil {
182			return UpgradeCheck{}, err
183		}
184		defer lock.release()
185		check, _, err := a.checkUpgradeLocked(slot, acceptedVersions, target)
186		if err != nil {
187			return UpgradeCheck{}, err
188		}
189		return check, nil
190	}
191	
192	// Upgrade 在检查通过后用目标规则生成一条新记录。
193	//
194	// 传入与 CheckUpgrade 相同的条件，并带调用方预期的最新记录标识 expected。
195	// 提交时在排他锁下重新判断当前来源：仍有阻碍则返回相同的阻碍信息并拒绝
196	// 写入；expected 为空或已不是该槽最新记录时返回现有冲突错误。
197	//
198	// 被拒绝的升级不增加历史记录，也不改变槽当前记录。成功后槽增加一条完整
199	// 的新记录，以被升级记录为父，保存目标规则；种子、时间片、角色位置及
200	// 物品数量和排列保持原样。并发升级或升级与普通覆盖竞争时，只有 expected
201	// 与最新记录一致的一个成功，其余收到冲突。
202	func (a *Archive) Upgrade(slot string, acceptedVersions []string, target Rules, expected RecordID) (UpgradeResult, error) {
203		if !validSlotName(slot) {
204			return UpgradeResult{}, &NotFoundError{Slot: slot}
205		}
206		if err := validateRules(target); err != nil {
207			return UpgradeResult{}, err
208		}
209		if expected == "" {
210			return UpgradeResult{}, &ConflictError{Slot: slot, Reason: "升级必须提供所依据的记录标识"}
211		}
212		lock, err := acquireLock(a.dir)
213		if err != nil {
214			return UpgradeResult{}, err
215		}
216		defer lock.release()
217	
218		oldPointer, err := a.readSlotPointerLocked(slot)
219		if err != nil {
220			return UpgradeResult{}, err
221		}
222		latest := oldPointer.Latest
223		if latest != expected {
224			return UpgradeResult{}, &ConflictError{
225				Slot:   slot,
226				Reason: "所依据的记录已不是该槽最新记录",
227			}
228		}
229	
230		check, env, err := a.checkUpgradeLocked(slot, acceptedVersions, target)
231		if err != nil {
232			return UpgradeResult{}, err
233		}
234		if !check.Compatible {
235			return UpgradeResult{Check: check}, &RuleError{
236				Reason: fmt.Sprintf("升级被阻碍: 目标规则无法承接当前角色状态（%d 处阻碍）", len(check.Blockers)),
237			}
238		}
239	
240		id, err := newRecordID()
241		if err != nil {
242			return UpgradeResult{}, err
243		}
244		newState := State{
245			Seed:       env.State.Seed,
246			Rules:      cloneRules(target),
247			Time:       env.State.Time,
248			Characters: cloneCharacters(env.State.Characters),
249		}
250		newEnv := &envelope{
251			Format:    archiveFormatVersion,
252			ID:        id,
253			Parent:    expected,
254			SlotFirst: false,
255			State:     newState,
256		}
257		newEnv.Checksum = computeChecksum(newEnv)
258		if err := writeRecord(a.dir, newEnv); err != nil {
259			return UpgradeResult{}, err
260		}
261		if err := a.commitSlotPointerLocked(slot, oldPointer, latest, id); err != nil {
262			return UpgradeResult{}, err
263		}
264		info := RecordInfo{
265			ID:      id,
266			Parent:  expected,
267			Version: target.Version,
268		}
269		return UpgradeResult{Check: check, Record: info}, nil
270	}
