package world

import (
	"fmt"
	"math"
)

// NameMapping 描述旧规则中一个名称到新规则名称的显式转换关系。
//
// From 必须是来源记录旧规则中存在的地点或物品种类，To 必须是目标规则中
// 存在的对应名称；空名称、来源不存在于旧规则或目标不存在于新规则都在
// 预览时返回规则错误。
type NameMapping struct {
	// From 是旧规则中的地点或物品种类名称。
	From string
	// To 是新规则中的对应名称。
	To string
}

// MigrationPreview 是把槽当前最新记录按对应关系显式迁移到目标规则的
// 预览结果。
//
// 预览只读：返回所依据的来源记录标识、旧新版本、按对应关系转换后的完整
// 世界状态（深拷贝）以及是否可提交。它不改变槽指向、历史或任何记录文件；
// 修改返回的状态也不影响存档。
type MigrationPreview struct {
	// RecordID 是所依据的来源记录标识（槽当前最新记录）。
	RecordID RecordID
	// OldVersion 是来源记录的规则版本。
	OldVersion string
	// TargetVersion 是目标规则版本。
	TargetVersion string
	// State 是转换后的完整世界状态（深拷贝），规则已替换为目标规则。
	// 正式迁移以排他锁下重新读取和计算的结果为准，不使用调用方可能改过
	// 的本状态。
	State State
	// Committable 表示转换后的状态能否在目标规则下提交（无阻碍）。
	Committable bool
	// Blockers 是全部阻碍，排序与升级检查一致；重复预览输出顺序一致。
	Blockers []Blocker
}

// MigrationResult 是正式迁移的返回结果。
type MigrationResult struct {
	// Preview 是对来源记录与目标规则的预览结果（排他锁下重新读取并计算）。
	Preview MigrationPreview
	// Record 是成功时新记录的元信息；被阻碍时为零值。
	Record RecordInfo
}

// validateMappings 校验转换对应关系：来源必须存在于旧规则，目标必须存在
// 于新规则，名称非空，同一来源不重复指定。即使没有角色使用这些名称也要
// 检查。
func validateMappings(old, target Rules, locations, items []NameMapping) error {
	oldLocs := make(map[string]struct{}, len(old.Locations))
	for _, l := range old.Locations {
		oldLocs[l] = struct{}{}
	}
	newLocs := make(map[string]struct{}, len(target.Locations))
	for _, l := range target.Locations {
		newLocs[l] = struct{}{}
	}
	if err := validateMappingSet("地点", locations, oldLocs, newLocs); err != nil {
		return err
	}

	oldKinds := make(map[string]struct{}, len(old.ItemKinds))
	for _, k := range old.ItemKinds {
		oldKinds[k] = struct{}{}
	}
	newKinds := make(map[string]struct{}, len(target.ItemKinds))
	for _, k := range target.ItemKinds {
		newKinds[k] = struct{}{}
	}
	return validateMappingSet("物品种类", items, oldKinds, newKinds)
}

func validateMappingSet(kind string, mappings []NameMapping, oldNames, newNames map[string]struct{}) error {
	seen := make(map[string]struct{}, len(mappings))
	for i, m := range mappings {
		if m.From == "" {
			return ruleErrorf("%s转换关系 %d 的来源名称为空", kind, i)
		}
		if m.To == "" {
			return ruleErrorf("%s转换关系 %d 的目标名称为空", kind, i)
		}
		if _, ok := oldNames[m.From]; !ok {
			return ruleErrorf("%s转换关系的来源 %q 不存在于旧规则", kind, m.From)
		}
		if _, ok := newNames[m.To]; !ok {
			return ruleErrorf("%s转换关系的目标 %q 不存在于新规则", kind, m.To)
		}
		if _, dup := seen[m.From]; dup {
			return ruleErrorf("%s转换关系的来源 %q 重复指定", kind, m.From)
		}
		seen[m.From] = struct{}{}
	}
	return nil
}

// applyMigration 按对应关系转换状态：角色按对应关系改变所在地点（无需
// 符合旧道路），物品改变种类但不增减数量；多个条目转换成同一种物品时
// 合并数量，按原列表中首次出现的位置保留一个条目。转换只作用于原始名称
// 一次，不沿对应关系连续替换，因此互换名称也有确定结果。未指定的名称
// 保持原样。种子、时间片、角色标识及角色排列保持不变。
//
// 合并数量或携带总量超出 int 范围时返回规则错误，不回绕也不丢弃物品。
func applyMigration(st State, locations, items []NameMapping) (State, error) {
	locLookup := make(map[string]string, len(locations))
	for _, m := range locations {
		locLookup[m.From] = m.To
	}
	itemLookup := make(map[string]string, len(items))
	for _, m := range items {
		itemLookup[m.From] = m.To
	}

	out := cloneState(st)

	for i := range out.Characters {
		if to, ok := locLookup[out.Characters[i].Location]; ok {
			out.Characters[i].Location = to
		}
	}

	for i := range out.Characters {
		ch := &out.Characters[i]
		merged := make([]CharacterItem, 0, len(ch.Items))
		indexByName := make(map[string]int, len(ch.Items))
		for _, it := range ch.Items {
			name := it.Item
			if to, ok := itemLookup[name]; ok {
				name = to
			}
			if idx, ok := indexByName[name]; ok {
				sum, ok := addInt(merged[idx].Count, it.Count)
				if !ok {
					return State{}, ruleErrorf("角色 %q 的物品 %q 合并数量超出整数范围", ch.ID, name)
				}
				merged[idx].Count = sum
			} else {
				indexByName[name] = len(merged)
				merged = append(merged, CharacterItem{Item: name, Count: it.Count})
			}
		}
		ch.Items = merged

		// 携带总量溢出检查：各物品数量都合法，但不同物品相加可能超出
		// int 范围，同样不能回绕或丢弃。
		total := 0
		for _, it := range ch.Items {
			sum, ok := addInt(total, it.Count)
			if !ok {
				return State{}, ruleErrorf("角色 %q 携带总量超出整数范围", ch.ID)
			}
			total = sum
		}
	}
	return out, nil
}

// addInt 做一次带溢出检查的 int 加法，返回结果与是否溢出。
func addInt(a, b int) (int, bool) {
	if b > 0 && a > math.MaxInt-b {
		return 0, false
	}
	if b < 0 && a < math.MinInt-b {
		return 0, false
	}
	return a + b, true
}

// migrationComputeLocked 在调用方已持锁（共享或排他均可）的前提下读取并
// 校验槽当前最新记录，校验转换对应关系，计算转换后的状态与阻碍。不写入。
func (a *Archive) migrationComputeLocked(slot string, acceptedVersions []string, target Rules, locations, items []NameMapping) (MigrationPreview, *envelope, error) {
	latest, err := a.readLatestLocked(slot)
	if err != nil {
		return MigrationPreview{}, nil, err
	}
	env, err := a.loadAndVerifyLocked(latest)
	if err != nil {
		if ce, ok := err.(*CorruptError); ok {
			ce.Slot = slot
		}
		return MigrationPreview{}, nil, err
	}
	if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
		return MigrationPreview{}, nil, &VersionRejectedError{
			Slot:     slot,
			Record:   latest,
			Version:  env.State.Rules.Version,
			Accepted: append([]string(nil), acceptedVersions...),
		}
	}
	if target.Version == env.State.Rules.Version {
		return MigrationPreview{}, nil, &RuleError{Reason: "目标规则版本必须与来源记录版本不同"}
	}
	if err := validateMappings(env.State.Rules, target, locations, items); err != nil {
		return MigrationPreview{}, nil, err
	}
	transformed, err := applyMigration(env.State, locations, items)
	if err != nil {
		return MigrationPreview{}, nil, err
	}
	// 转换后的状态保存目标规则。
	transformed.Rules = cloneRules(target)
	blockers := checkCompatibility(transformed, target)
	preview := MigrationPreview{
		RecordID:      latest,
		OldVersion:    env.State.Rules.Version,
		TargetVersion: target.Version,
		State:         transformed,
		Committable:   len(blockers) == 0,
		Blockers:      blockers,
	}
	return preview, env, nil
}

// PreviewMigration 预览把槽当前最新记录按对应关系显式迁移到目标规则。
//
// 传入槽名、可接受的旧版本集合、目标规则，以及旧地点到新地点、旧物品到
// 新物品的对应关系，返回所依据的来源记录标识、旧新版本、转换后的完整
// 世界状态（深拷贝）及是否可提交。转换只作用于原始名称一次，不沿对应
// 关系连续替换；未指定的名称保持原样。转换后仍有缺失地点、不被允许的
// 物品或超过目标携带上限时，一次列出全部阻碍，重复预览输出顺序一致。
//
// 预览只读：不改变世界、历史或槽当前记录，修改返回的状态也不影响存档。
// 目标规则须满足规则自身的合法性要求且版本与来源不同；对应关系的来源
// 必须存在于旧规则、目标必须存在于新规则（即使没有角色使用也要检查），
// 空目标或未知名称返回规则错误；合并数量或携带总量超出 int 范围返回规则
// 错误。来源缺失、损坏或版本不被接受时沿用已有对应错误，不自动挑选历史
// 记录。
func (a *Archive) PreviewMigration(slot string, acceptedVersions []string, target Rules, locations, items []NameMapping) (MigrationPreview, error) {
	if !validSlotName(slot) {
		return MigrationPreview{}, &NotFoundError{Slot: slot}
	}
	if err := validateRules(target); err != nil {
		return MigrationPreview{}, err
	}
	lock, err := acquireSharedLock(a.dir)
	if err != nil {
		return MigrationPreview{}, err
	}
	defer lock.release()
	preview, _, err := a.migrationComputeLocked(slot, acceptedVersions, target, locations, items)
	if err != nil {
		return MigrationPreview{}, err
	}
	return preview, nil
}

// Migrate 在预览后正式迁移：用目标规则与转换后的状态生成一条以来源为父
// 的新记录并加入本槽保存次序。
//
// 传入与预览相同的条件，并带预览返回的来源记录标识 source。提交时在
// 排他锁下重新读取并完整校验来源，重新校验目标规则与对应关系、重新计算
// 转换后的状态与阻碍，绝不使用调用方可能改过的预览状态：
//
//   - source 为空，或槽已不再指向该来源（被并发覆盖、升级、确认恢复或
//     另一次迁移抢先提交），返回 *ConflictError。
//   - 来源缺失、损坏或版本不被接受分别返回已有的不存在、损坏或版本拒绝
//     错误，不改选其他记录。
//   - 仍有阻碍时返回阻碍信息并拒绝保存，不改变当前记录或历史。
//
// 成功后产生一条以来源为父的新记录，保存目标规则与转换后的状态，加入
// 本槽保存次序；种子、时间片、角色标识及角色排列保持原样。与覆盖、升级、
// 确认恢复或另一次迁移竞争时，同一来源最多一个成功。任何拒绝都不改变
// 当前记录或历史；中断后重开只能看到迁移前或迁移后的完整记录与历史。
// 旧记录及已有分支保留原状态，恢复读取仍能找到旧版本；迁移后的记录可
// 继续按新规则移动、改变物品并保存，普通读取不自动转换。
func (a *Archive) Migrate(slot string, acceptedVersions []string, target Rules, locations, items []NameMapping, source RecordID) (MigrationResult, error) {
	if !validSlotName(slot) {
		return MigrationResult{}, &NotFoundError{Slot: slot}
	}
	if source == "" {
		return MigrationResult{}, &ConflictError{Slot: slot, Reason: "迁移必须提供所依据的来源记录标识"}
	}
	if err := validateRules(target); err != nil {
		return MigrationResult{}, err
	}
	lock, err := acquireLock(a.dir)
	if err != nil {
		return MigrationResult{}, err
	}
	defer lock.release()

	oldPointer, err := a.readSlotPointerLocked(slot)
	if err != nil {
		return MigrationResult{}, err
	}
	// 乐观并发控制：槽必须仍指向预览时的来源记录。
	if oldPointer.Latest != source {
		return MigrationResult{}, &ConflictError{
			Slot:   slot,
			Reason: "所依据的来源记录已不是该槽最新记录",
		}
	}

	// 排他锁下重新读取、校验并计算，不采信调用方带回的任何状态。
	preview, _, err := a.migrationComputeLocked(slot, acceptedVersions, target, locations, items)
	if err != nil {
		return MigrationResult{}, err
	}
	if !preview.Committable {
		return MigrationResult{Preview: preview}, &RuleError{
			Reason: fmt.Sprintf("迁移被阻碍: 转换后的状态无法在目标规则下提交（%d 处阻碍）", len(preview.Blockers)),
		}
	}

	id, err := newRecordID()
	if err != nil {
		return MigrationResult{}, err
	}
	newEnv := &envelope{
		Format:    archiveFormatVersion,
		ID:        id,
		Parent:    source,
		SlotFirst: false,
		// 保存目标规则与转换后的状态；种子、时间片、角色标识及排列原样。
		State: preview.State,
	}
	newEnv.Checksum = computeChecksum(newEnv)
	if err := writeRecord(a.dir, newEnv); err != nil {
		return MigrationResult{}, err
	}
	// 记录完整落盘后才原子更新指针：新记录前置进保存次序，旧历史原样
	// 保留。崩溃在这一步之前，槽保持迁移前的指向与历史，新记录因不在
	// 历史索引中而不会进入恢复候选。
	if err := a.commitSlotPointerLocked(slot, oldPointer, source, id); err != nil {
		return MigrationResult{}, err
	}
	info := RecordInfo{
		ID:      id,
		Parent:  source,
		Version: target.Version,
	}
	return MigrationResult{Preview: preview, Record: info}, nil
}

// Package world 提供带规则约束的本地世界与命名存档槽。
//
// # 世界与规则
//
// 用 [NewWorld] 建立世界：需要整数地图种子、非空规则版本、地点及其
// 连通关系、角色、物品。时间片从 0 开始。地点与角色标识不得重复，
// 连通关系只能引用已有地点，携带上限不能为负；角色必须位于已有地点，
// 物品数量必须为非负整数且总量不超过其携带上限。初始数据不合法时
// [NewWorld] 返回 *RuleError，不会建立世界。
//
// 用 [World.Apply] 一次原子提交多个移动、物品数量变化和时间推进：
// 移动只能沿规则允许的连通关系，不能引用不存在的角色或物品，不能让
// 数量变负或总量超过上限，时间不能倒退。任意一项违反规则，整次提交
// 失败，世界保持提交前状态。[World.Snapshot] 与 Apply 返回的状态都
// 是深拷贝，修改它们不会影响世界或已保存记录。
//
// # 存档
//
// [Create] 在指定目录建立存档，[Open] 重新打开。Save 首次保存创建
// 命名槽，重名明确拒绝；Replace 覆盖时必须带上此前读到的记录标识，
// 且它仍是该槽最新记录才允许写入。每次成功保存都产生目录内唯一的
// 记录标识，保存完整世界数据、父记录标识和内容校验和（校验和覆盖父
// 记录关系）。同一目录的多个进程或实例并发覆盖同一父记录时，flock
// 与记录标识比较保证只有一个成功，其余收到 *ConflictError。所有写入
// 都先写临时文件再原子改名，崩溃后重开只能看到旧的完整记录或新的
// 完整记录。
//
// [Archive.Branch] 可从某槽的一次历史记录分出新槽，新槽首条记录以它
// 为父并完整复制当时的种子、规则和状态，此后两槽互不影响。覆盖后的
// 历史记录仍可按标识读取。
//
// 槽指针除指向当前最新记录外，还内嵌一份按“保存生效次序”排列的历史
// 索引（最新在前）。该索引只在记录文件完整落盘、保存完整生效后才随
// 指针原子更新，因此残留临时文件、写完但未完成保存的孤儿记录，以及
// CAS 竞争失败的写入都不会出现在索引中。旧版本写出的裸指针（无历史
// 索引）仍可直接打开和读取：读取时在内存中沿校验通过的父链回退重建，
// 不要求用户转换数据；该槽第一次成功覆盖或升级后，重建出的原有历史与
// 新记录会一并持久化，旧历史从此获得完整恢复能力。读取与恢复读取本身
// 都不改写目录内容。
//
// 读取（[Archive.Latest]、[Archive.Record]）会检查内容校验和、父记录
// 关系与规则版本。调用方显式给出可接受版本集合；版本不被接受返回
// *VersionRejectedError，且不会替换记录中的规则。最新记录损坏、被删除、
// 被截断成无法解析的内容，或连同若干中间记录一起损坏/版本不被接受时，
// [Archive.RecoverLatest] 依据历史索引按保存次序（与文件修改时间和世界
// 时间片大小无关）回溯，返回该槽最近一份校验通过且版本可接受的已保存
// 记录；它不会因为损坏文件里读不出父标识而提前放弃，也不信任其中被
// 篡改的父标识或槽首标记，因此恢复既不会被引向别的槽，也不会遮住本槽
// 更早的可用记录。分支槽只在分支自身成功保存的记录中查找，即使分支
// 首条记录损坏也不越过分支边界，其他槽即使种子和规则相同也不替代。
// 分支全无可用记录、或没有任何版本可接受的完好记录时，返回可用
// errors.Is 判断的 ErrUnrecoverable；槽不存在仍报不存在，槽指针不可读
// 仍报损坏。读取与恢复读取都不会改写存档。
//
// # 预览恢复与确认恢复
//
// [Archive.RecoverLatest] 只回答“能恢复到哪份记录”，不改变槽当前指向。
// 需要正式恢复时先用 [Archive.PreviewRecovery] 预览：传入槽名与可接受
// 规则版本集合，返回槽当前指向的记录标识、按本槽保存生效次序选中的来源
// 记录标识，以及来源记录的完整世界状态（深拷贝）。选择规则与恢复读取
// 相同——最近一份内容与父关系校验通过且版本可接受的记录，越过缺失、截断、
// 校验失败与版本不被接受的记录，分支只用自己的历史；槽当前记录本就完好
// 且版本可接受时可以选它本身。槽不存在报不存在，槽指针无法解析报损坏
// （仍会返回其当前标识，即使该记录已损坏或被删除），没有可用记录返回
// ErrUnrecoverable。预览绝不写入、修补或删除任何数据，可重复调用。
//
// [Archive.ConfirmRecovery] 依据预览结果正式恢复：传入槽名、预览中的当前
// 记录标识与来源记录标识，以及可接受版本集合。任一标识为空，或槽已不再
// 指向该当前记录（被并发覆盖、升级或另一次确认抢先提交），都返回现有的
// *ConflictError；当前标识只与槽所指记录比较，即使它已损坏或被删除，也
// 不妨碍从本槽完好旧记录恢复。确认在排他锁下重新读取并完整校验来源，不
// 使用调用方可能修改过的预览状态：来源必须仍属于该槽、仍通过内容与父
// 关系校验且版本可接受；其他槽的记录与未生效的残留/孤儿记录按不存在
// 拒绝，来源后来被删除、损坏或版本不被接受时分别返回已有的不存在、损坏
// 或版本拒绝错误，不改选其他来源。
//
// 成功确认后产生一条独立的新记录（即使来源就是当前记录）：槽指向新记录，
// 父记录是选中的来源，种子、完整规则、时间片、角色及物品的内容和排列均
// 原样复制，允许时间片回到来源时刻。旧历史按原保存次序保留，新记录排在
// 最前；来源之后仍完好的旧记录可照常读取或分支，已存在的分支不受影响。
// 同一当前标识上的并发确认、以及确认与普通覆盖或规则升级竞争时，flock
// 与标识比较保证最多一个成功。重新打开存档后可以读新记录并继续提交、
// 覆盖或升级；旧格式存档沿用已有的历史归属限制，第一次成功确认后重建出
// 的旧历史与新记录一并持久化。写入中断后重开，槽只能保持确认前的指向和
// 历史，或同时看到新记录与更新后的历史；尚未生效的新记录不会进入恢复
// 候选，也不能作为来源。
//
// # 规则升级
//
// [Archive.CheckUpgrade] 检查槽当前最新记录能否在目标规则下继续使用：
// 传入槽名、可接受的旧版本集合与目标规则，返回所检查的记录标识、旧版本、
// 目标版本、是否兼容及具体阻碍。检查只读取来源记录并计算兼容性，不改变
// 世界、历史或槽当前记录。目标规则须先满足规则自身的合法性要求，且版本
// 与来源记录不同（版本只按相等判断，不按数字大小限制升级）。兼容只判断
// 能否原样承接当前角色状态：每个角色所在地点仍存在，已列出的物品种类仍被
// 允许（数量为零也算），各角色携带总量不超过目标上限；目标中没有该角色
// 上限时表示不设上限。允许删去无人所在的地点、不再出现的物品种类或旧
// 连通关系，也允许增加内容。多个阻碍一次返回全部，同类问题按角色标识、
// 物品标识排序，重复检查输出顺序一致。
//
// [Archive.Upgrade] 在检查通过后用目标规则生成一条新记录：传入与检查
// 相同的条件，并带调用方预期的最新记录标识。提交时在排他锁下重新判断
// 当前来源，仍有阻碍则返回相同的阻碍信息并拒绝写入；预期标识为空或已
// 不是该槽最新记录时返回现有冲突错误。被拒绝的升级不增加历史记录，也不
// 改变槽当前记录。成功后槽增加一条完整的新记录，以被升级记录为父，保存
// 目标规则；种子、时间片、角色位置及物品数量和排列保持原样。并发升级或
// 升级与普通覆盖竞争时，只有预期标识与最新记录一致的一个成功，其余收到
// 冲突。旧记录继续保留原规则，已经分出的分支不受影响；重新打开存档后能
// 读取新记录并继续提交，只接受旧版本的恢复读取仍能找到升级前最近一份
// 可用记录。写入中断后，槽只能指向升级前或升级后的完整记录。普通读取
// 不会自动升级；调用方修改检查结果、目标规则或读回的状态，不应影响已
// 保存的数据。
//
// # 显式迁移旧存档
//
// 升级只能原样承接角色状态。需要在地点或物品改名、合并后仍保留角色继续
// 使用新规则时，用 [Archive.PreviewMigration] 与 [Archive.Migrate] 显式
// 迁移：传入槽名、可接受的旧版本集合、目标规则，以及旧地点到新地点、
// 旧物品到新物品的对应关系。目标规则须合法且版本与来源不同；每个对应
// 关系的来源必须存在于旧规则、目标必须存在于新规则（即使暂时没有角色
// 使用也要检查），空目标或未知名称返回规则错误。未指定的名称保持原样，
// 所有转换只作用于原始名称一次，不沿对应关系连续替换，因此互换名称也有
// 确定结果。
//
// 角色按对应关系改变所在地点（无需符合旧道路），物品改变种类但不增减
// 数量；多个条目转换成同一种物品时合并数量，按原列表中首次出现的位置
// 保留一个条目，零数量仍保留并参与种类检查。种子、时间片、角色标识及
// 角色排列保持不变。合并数量或携带总量超出 int 范围时返回规则错误，不
// 回绕也不丢弃物品。
//
// [Archive.PreviewMigration] 先给出预览：返回来源记录标识、旧新版本、
// 转换后的完整状态及是否可提交。转换后仍有缺失地点、不被允许的物品或
// 超过目标携带上限时，一次列出全部阻碍，注明角色和相关名称或数量，重复
// 预览顺序一致。预览不改动存档，修改返回状态也不影响来源。来源缺失、
// 损坏或版本不被接受时沿用已有对应错误，不自动挑选历史记录。
//
// [Archive.Migrate] 正式迁移：需带预览的来源标识，并重新提交目标规则与
// 对应关系；提交时在排他锁下重新读取和计算，不直接保存调用方改过的预览
// 状态。来源标识为空或槽已更新时返回冲突；仍有阻碍时返回阻碍并拒绝
// 保存。成功生成以来源为父的新记录，保存目标规则与转换后的状态，加入
// 本槽保存次序。与覆盖、升级、确认恢复或另一次迁移竞争时，同一来源最多
// 一个成功。任何拒绝都不改变当前记录或历史；中断后重新打开只能看到迁移
// 前或迁移后的完整记录与历史。旧记录及已有分支保留原状态，恢复读取仍能
// 找到旧版本；迁移后的记录可继续按新规则移动、改变物品并保存，普通读取
// 不自动转换。
package world

// Ready 表示基线可以运行。
func Ready() bool { return true }

