	if !errors.As(err, &re) {
		t.Fatalf("期望 *RuleError，得到 %T", err)
	}
}

func TestApplyMergeTotalOverflowWithLimitRejected(t *testing.T) {
	// 角色有携带上限 5，原数量 1，同批增减后最终数量合法但总量超上限，应拒绝。
	w := baseWorld(t)
	_, err := w.Apply(Commit{
