}

func TestApplyNoLimitLargeTotalAllowed(t *testing.T) {
	// 未设上限的角色，单种数量合法但总量超过 int 最大值，应允许提交。
	rules := baseRules()
	delete(rules.CarryLimits, "hero")
	w, err := NewWorld(InitialData{
		Seed:  1,
		Rules: rules,
		Characters: []Character{
